package com.forgerag.agent;

import java.util.ArrayList;
import java.util.List;

/**
 * Shared state object threaded through every node in the LangGraph4j graph.
 *
 * Design principle: every node reads from and writes to this one object —
 * keeps data flow explicit and testable. See ARCHITECTURE.md.
 *
 * Fields:
 *  - query              current search query (rewritten by QueryRewriterNode on retry)
 *  - originalQuery      user's original query (never mutated)
 *  - retrievedContext   chunk texts from RetrievalNode or WebSearchNode
 *  - draftAnswer        generated by GenerationNode
 *  - verdict            "VALID" | "HALLUCINATED" — set by EvaluationNode
 *  - evaluationReasoning LLM-judge's explanation
 *  - retryCount         rewrite-and-retry cycles so far
 *  - maxRetries         cap from application.properties
 *  - retrievalConfident whether top vector-similarity score exceeded the threshold
 *  - webSearchUsed      true when CRAG triggered the WebSearchNode fallback
 *  - webSearchSources   citation URLs returned by Gemini Google Search grounding
 */
public class AgentState {

    private String query;
    private String originalQuery;
    private List<String> retrievedContext = new ArrayList<>();
    private String draftAnswer;
    private String verdict;
    private String evaluationReasoning;
    private int retryCount = 0;
    private int maxRetries;

    // ── CRAG web-search fallback ───────────────────────────────────────────
    private boolean retrievalConfident = true;   // assume confident; RetrievalNode overrides
    private boolean webSearchUsed      = false;
    private List<String> webSearchSources = new ArrayList<>();

    public AgentState() {}

    public AgentState(String query, int maxRetries) {
        this.query = query;
        this.originalQuery = query;
        this.maxRetries = maxRetries;
    }

    // ── Accessors ──────────────────────────────────────────────────────────

    public String getQuery() { return query; }
    public void setQuery(String query) { this.query = query; }

    public String getOriginalQuery() { return originalQuery; }
    public void setOriginalQuery(String originalQuery) { this.originalQuery = originalQuery; }

    public List<String> getRetrievedContext() { return retrievedContext; }
    public void setRetrievedContext(List<String> retrievedContext) { this.retrievedContext = retrievedContext; }

    public String getDraftAnswer() { return draftAnswer; }
    public void setDraftAnswer(String draftAnswer) { this.draftAnswer = draftAnswer; }

    public String getVerdict() { return verdict; }
    public void setVerdict(String verdict) { this.verdict = verdict; }

    public String getEvaluationReasoning() { return evaluationReasoning; }
    public void setEvaluationReasoning(String reason) { this.evaluationReasoning = reason; }

    public int getRetryCount() { return retryCount; }
    public void incrementRetryCount() { this.retryCount++; }

    public int getMaxRetries() { return maxRetries; }
    public void setMaxRetries(int maxRetries) { this.maxRetries = maxRetries; }

    public boolean isRetryLimitReached() { return retryCount >= maxRetries; }

    public boolean isGrounded() { return "VALID".equalsIgnoreCase(verdict); }

    // ── CRAG accessors ────────────────────────────────────────────────────

    public boolean isRetrievalConfident() { return retrievalConfident; }
    public void setRetrievalConfident(boolean retrievalConfident) { this.retrievalConfident = retrievalConfident; }

    public boolean isWebSearchUsed() { return webSearchUsed; }
    public void setWebSearchUsed(boolean webSearchUsed) { this.webSearchUsed = webSearchUsed; }

    public List<String> getWebSearchSources() { return webSearchSources; }
    public void setWebSearchSources(List<String> webSearchSources) { this.webSearchSources = webSearchSources; }

    @Override
    public String toString() {
        return "AgentState{query='" + query + "', retryCount=" + retryCount +
               ", verdict='" + verdict + "', grounded=" + isGrounded() +
               ", webSearchUsed=" + webSearchUsed + "}";
    }
}
